import java.util.*;

class Solution {
    private static int gcd(int a, int b) { return b == 0 ? Math.abs(a) : gcd(b, a % b); }

    public int getMinimumRoutes(int[][] pickupLocations, int baseX, int baseY) {
        Set<Long> dirs = new HashSet<>();
        for (int[] p : pickupLocations) {
            int dx = p[0] - baseX, dy = p[1] - baseY;
            if (dx == 0 && dy == 0) continue;
            int g = gcd(dx, dy);
            dirs.add((long) (dx / g) * 100000L + (dy / g));
        }
        return dirs.size();
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int getMinimumRoutes(vector<vector<int>>& pickupLocations, int baseX, int baseY) {
        set<pair<int, int>> dirs;
        for (auto& p : pickupLocations) {
            int dx = p[0] - baseX, dy = p[1] - baseY;
            if (dx == 0 && dy == 0) continue;
            int g = std::gcd(abs(dx), abs(dy));
            dirs.insert({dx / g, dy / g});
        }
        return dirs.size();
    }
};
